'use strict';
const {performance}=require('node:perf_hooks');
const {randomFillSync}=require('node:crypto');
// One shared 200 MB probe: 3 x 50 MB down and 2 x 25 MB generated bytes up.
async function measure({fetcher=fetch,clock=()=>performance.now(),fill=randomFillSync}={}){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);
 const options={cache:'no-store',credentials:'omit',redirect:'error',signal:controller.signal};
 const down=[],up=[];
 try{
  for(let i=0;i<3;i++){
   const start=clock(),r=await fetcher('https://speed.cloudflare.com/__down?bytes=50000000',options);
   if(!r.ok)throw new Error('Download unavailable');
   let count=0;for await(const chunk of r.body)count+=chunk.length;
   const elapsed=clock()-start;if(count!==50000000||elapsed<=0)throw new Error('Incomplete download');
   down.push(count*8/elapsed/1000);
  }
  const bytes=new Uint8Array(25000000);fill(bytes);
  for(let i=0;i<2;i++){
   const start=clock(),r=await fetcher('https://speed.cloudflare.com/__up',{...options,method:'POST',headers:{'Content-Type':'application/octet-stream'},body:bytes});
   if(!r.ok)throw new Error('Upload unavailable');await r.arrayBuffer();
   const elapsed=clock()-start;if(elapsed<=0)throw new Error('Invalid timing');up.push(bytes.length*8/elapsed/1000);
  }
  return {downMbps:Math.max(...down),upMbps:Math.max(...up),downloadSamples:down,uploadSamples:up,transferredBytes:200000000,target:'Cloudflare HTTP',method:'Best of 3 download / 2 upload; includes HTTP overhead'};
 }finally{clearTimeout(timer);}
}
module.exports={measure};
